// Cross-checks the Dart protocol port against vectors generated by the
// TypeScript implementation (regenerate with `GEN_GOLDEN=1 npm test` at the repo root).
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:distance_bits/core/core.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  final golden = jsonDecode(File('test/golden.json').readAsStringSync()) as Map<String, dynamic>;

  test('PRNG matches TypeScript bit for bit', () {
    final r = Prng(12345);
    for (final v in golden['prng'] as List) {
      expect(r.next(), v);
    }
    final seeds = [chunkSeed(0, 0), chunkSeed(77, 5), chunkSeed(255, 123456), chunkSeed(3, 2147483648 + 7)];
    expect(seeds, golden['seeds']);
  });

  test('fountain chunks match TypeScript', () {
    final data = Uint8List.fromList(List.generate(300, (i) => (i * 37 + 11) & 0xff));
    (golden['fountain'] as Map<String, dynamic>).forEach((l, chunks) {
      final enc = LTEncoder(Uint8List.sublistView(data, 0, int.parse(l)), 42);
      final got = List.generate(400, enc.chunk);
      expect(got, chunks, reason: 'L=$l');
    });
  });

  test('transmitted frame streams match TypeScript for every preset/palette', () {
    for (final s in golden['streams'] as List) {
      final preset = PresetName.values.byName(s['preset'] as String);
      final palette = PaletteName.values.byName(s['palette'] as String);
      final cfg = Config(preset, palette, s['fps'] as int);
      final tx = Transmitter(cfg, encodePayload(Payload.text(s['text'] as String)), msgId: 77);
      expect(tx.epochChunks, s['epochChunks']);
      expect(tx.framesPerEpoch(), closeTo((s['framesPerEpoch'] as num).toDouble(), 1e-9));
      final frames = s['frames'] as List;
      for (var i = 0; i < frames.length; i++) {
        final f = tx.next();
        expect('${f.layout.name[0]}${f.segment.name[0]}${f.epoch}:${f.cells.join()}', frames[i], reason: '$cfg "${(s['text'] as String).substring(0, 2)}" frame $i');
      }
    }
  });
}
